export function createWeek(number,settings={}){return {id:crypto.randomUUID(),number,startedAt:new Date().toISOString(),archivedAt:null,days:Object.fromEntries(DAYS.map(day=>[day,{current:ROUTINES[day][0].id,entries:ROUTINES[day].map(e=>({...structuredClone(e),...settings[day+':'+e.id],completed:false,completedAt:null,weight:null,reps:null,effort:null,precision:'exact',variant:null}))}]))};}
export function initialState(){return {schema:1,appId:'luke-training',programmeVersion:1,revision:0,active:createWeek(1),archives:[],seed:structuredClone(SEED),settings:{},view:{page:'home',day:null}};}
export const remaining=(session)=>session.entries.filter(e=>!e.completed);
export function currentEntry(session){return session.entries.find(e=>e.id===session.current)||session.entries[0];}
export function navigate(session,delta){const r=session.entries;if(!r.length)return;const i=r.findIndex(e=>e.id===session.current);session.current=r[(Math.max(0,i)+delta+r.length)%r.length].id;}
export const isBodyweightOnly=e=>['muscle-ups','pull-ups'].includes(e.id);
export function missingExerciseFields(e){return [isBodyweightOnly(e)||typeof e.weight==='number'&&Number.isFinite(e.weight)&&e.weight>=0?null:'weight',Number.isInteger(e.reps)&&e.reps>0?null:'reps',['more','right','hard'].includes(e.effort)?null:'effort'].filter(Boolean);}
export function completeEntry(session,id){const entry=session.entries.find(e=>e.id===id);if(!entry||entry.completed)return false;if(missingExerciseFields(entry).length)throw new Error(isBodyweightOnly(entry)?'Log reps and effort before completing this exercise.':'Log weight, reps and effort before completing this exercise.');if(isBodyweightOnly(entry)){entry.weight=null;entry.unit='bodyweight';entry.precision='exact';}entry.completed=true;entry.completedAt=new Date().toISOString();return true;}
export function archiveWeek(state){state.active.archivedAt=new Date().toISOString();state.archives.push(state.active);state.active=createWeek(state.active.number+1,state.settings);state.view={page:'home',day:null};}

export const loadUnit=e=>e.loadUnit??'kg';
export const unitSuffix=e=>loadUnit(e)==='unknown'?'':loadUnit(e);
export function weightText(e){return e.weight===null?(isBodyweightOnly(e)?'Bodyweight':'Weight not logged'):(e.precision==='estimated'?'≈ ':'')+e.weight+(unitSuffix(e)?' '+unitSuffix(e):'');}
export function repRange(e){const nums=e.target.match(/\d+/g)?.map(Number);if(!nums?.length)throw new Error('Missing rep target');const max=Math.max(10,Math.ceil(Math.max(...nums)*1.2/5)*5);const step=Math.ceil(max/6/5)*5;const values=[];for(let n=0;n<max;n+=step)values.push(n);values.push(max);return {min:0,max,values};}
export function repInputValue(e){const {min,max}=repRange(e);return e.reps!==null?Math.min(max,Math.max(min,e.reps)):min;}
export function historicalText(e){return e.recordedSets?e.recordedReps:[weightText(e),e.recordedReps?e.recordedReps+' reps':e.reps!=null?e.reps+' reps':null].filter(Boolean).join(' · ');}
// Compact display only: retain every original set and note in the saved history.
export function previousSummary(e){
 const mean=values=>String(Math.round(values.reduce((sum,n)=>sum+n,0)/values.length*10)/10);
 const format=(record,values)=>weightText(record)+(values.length?' × '+mean(values)+' reps':'');
 if(Array.isArray(e.recordedSets)&&e.recordedSets.length){
  // Different loads have separate averages; never invent a representative weight.
  const groups=new Map();
  for(const set of e.recordedSets){if(!Number.isFinite(set.reps))continue;const weight=set.weight??null;if(!groups.has(weight))groups.set(weight,[]);groups.get(weight).push(set.reps);}
  if(groups.size)return [...groups].map(([weight,values])=>format({...e,weight},values)).join(' · ');
 }
 const values=typeof e.recordedReps==='string'?e.recordedReps.split('/').map(set=>/^\s*(\d+(?:\.\d+)?)/.exec(set)).filter(Boolean).map(match=>Number(match[1])):Number.isFinite(e.reps)?[e.reps]:[];
 return format(e,values);
}
export function previousResult(state,day,entry){
 // The active week never participates, so saving or undoing this week's result cannot replace its reference.
 // Shared exercises can use another day's earlier result; seated and standing raises are distinct.
 const identity=(d,e)=>d+':'+e.id;
 const matches=(e,d)=>identity(d,e)===identity(day,entry)&&(e.weight!=null||e.reps!=null||e.effort!=null||e.recordedReps)&&(e.variant??null)===(entry.variant??null);
 const candidates=[];
 for(const week of state.archives){
  if(week.id===state.active.id||week.number>=state.active.number)continue;
  for(const recordedDay of DAYS)for(const e of week.days[recordedDay]?.entries??[])if(e.completed&&matches(e,recordedDay))candidates.push({...e,day:recordedDay,date:e.completedAt??week.archivedAt??week.startedAt,week:week.number});
 }
 for(const e of state.seed){
  if(!matches(e,e.day)||e.completed===false)continue;
  // Retired entries from this active week are preserved in seed, but are not an earlier result.
  if(e.sourceId?.includes(state.active.id))continue;
  if(e.date&&Date.parse(e.date)>=Date.parse(state.active.startedAt))continue;
  candidates.push({...e});
 }
 const timestamp=e=>Date.parse(e.date)||0;
 candidates.sort((a,b)=>timestamp(b)-timestamp(a)||(b.week??0)-(a.week??0));
 return candidates[0]??null;
}
export function validateState(s){
 const fail=()=>{throw new Error('This file is not a compatible Luke Training backup. Nothing was changed.');};
 const str=(x,n=250)=>typeof x==='string'&&x.length<=n;
 const number=x=>typeof x==='number'&&Number.isFinite(x)&&x>=0&&x<=10000;
 const reps=x=>x===null||Number.isInteger(x)&&x>=0&&x<=1000;
 const measure=e=>e.loadUnit===undefined||['kg','lb','unknown'].includes(e.loadUnit);
 if(!s||s.appId!=='luke-training'||s.schema!==1||!Number.isInteger(s.revision)||s.revision<0||!Array.isArray(s.archives)||s.archives.length>5000||!Array.isArray(s.seed)||s.seed.length>1000||!s.settings||typeof s.settings!=='object'||Array.isArray(s.settings))fail();
 const ids=new Set();
 for(const w of [...s.archives,s.active]){
  if(!w||!str(w.id)||ids.has(w.id)||!Number.isInteger(w.number)||w.number<1||!w.days)fail();ids.add(w.id);
  for(const d of DAYS){const ses=w.days[d];if(!ses||!Array.isArray(ses.entries)||ses.entries.length>100)fail();const seen=new Set();
   for(const e of ses.entries){if(!e||!str(e.id)||seen.has(e.id)||!str(e.name)||!(e.variants===null||Array.isArray(e.variants)&&e.variants.length<=20&&e.variants.every(v=>str(v)))||!(e.completedAt===null||str(e.completedAt))||!str(e.target)||!str(e.unit)||typeof e.completed!=='boolean'||!number(e.sets)||!(e.weight===null||number(e.weight))||!reps(e.reps)||!measure(e)||![null,'more','right','hard'].includes(e.effort)||!(e.increment===null||number(e.increment)&&e.increment>0)||!(e.variant===null||str(e.variant))||!['exact','estimated'].includes(e.precision))fail();seen.add(e.id);}
   if(!(ses.current===null||seen.has(ses.current)))fail();
  }
 }
 for(const e of s.seed)if(!e||!DAYS.includes(e.day)||!str(e.id)||!(e.weight===null||number(e.weight))||!reps(e.reps)||!str(e.unit)||!measure(e)||!['exact','estimated'].includes(e.precision)||!(e.date==null||str(e.date)))fail();
 for(const [key,v] of Object.entries(s.settings))if(!str(key)||!DAYS.some(d=>key.startsWith(d+':'))||!v||!str(v.unit)||!number(v.increment)||v.increment<=0||!measure(v)||Object.keys(v).some(k=>!['unit','increment','loadUnit'].includes(k)))fail();
 if(!s.view||!['home','day','history','backup','review','progress'].includes(s.view.page)||!(s.view.day===null||DAYS.includes(s.view.day)))fail();
 return s;
}
export function migrateState(s){return structuredClone(validateState(s));}
export function toCSV(s){
 const rows=[['Cycle','Day','Exercise','Variant','Sets','Target reps','Completed','Weight','Measurement unit','Weight type','Weight precision','Reps','Effort','Date','Source','Sets source','Recorded sets','Notes']];
 for(const w of [...s.archives,s.active])for(const d of DAYS)for(const e of w.days[d].entries)rows.push([w.number,d,e.name,e.variant,e.sets,e.target,e.completed,e.weight,loadUnit(e),e.unit,e.precision,e.reps,e.effort,e.completedAt,'app','routine','','']);
 for(const e of s.seed)rows.push(['Historical',e.day,e.name??e.id,e.variant,e.sets,e.target??'',e.completed??true,e.weight,loadUnit(e),e.unit,e.precision,e.reps,e.effort,e.date,e.source,e.sets_source,e.recordedReps,e.notes]);
 return rows.map(r=>r.map(v=>'\"'+String(v??'').replaceAll('\"','\"\"')+'\"').join(',')).join('\r\n');
}

export const weekComplete=w=>DAYS.every(d=>w.days[d].entries.every(e=>e.completed));
